-- Venue Live Guest "Wedding Adat Gorontalo". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara gorontalo), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'gorontalo', 'Wedding Adat Gorontalo', 'gorontalo', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 141, 'center 38%',
  $t${"name":"Adat Gorontalo","orn":"diamond","ui":{"ivory":"#FBF5E8","white":"#FFFFFF","soft":"#EAD8C0","soft2":"#C9A24A","accent":"#7A2470","deep":"#2E1030","ink":"#2E1030","mute":"#8A6A86","line":"#E6D6C6","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F8EFDC","ink":"#2E1030","accent":"#7A2470","gold":"#C9A24A","leaf":"#EAD8C0","hbg":"rgba(251,245,232,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(46,16,48,.9)","acc":"#F2C94C","on":"#2E1030"},"scr":{"wine":"#2E1030","veil":"251,245,232"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'gorontalo');
